fn mem_free(h: &mut MgHost, vm: &mut V) -> R {
    let p = vm.a(0);
    if let Some(&cap) = h.blocks.get(&p) {
        let list = h.free_blocks.entry(cap).or_default();
        if !list.contains(&p) {
            list.push(p);
        }
    }
    Ok(())
}

